//! Inkling 2 request preparation against tml-renderers references.
//!
//! The checkpoint tests read `tokenizer.json` from FLARE_INKLING2_TEST_SNAPSHOT
//! (thinkingmachines/Inkling-2-Small at the fixture revision) and compare Helios
//! with tests/frontend/inkling2_tml.json, generated by
//! tests/frontend/generate_inkling2_fixtures.py.

use super::*;
use crate::frontend::{Asset, FrontendAssets, FrontendSettings};
use crate::server::protocol::{Protocol, decode};
use serde_json::json;
use sha2::{Digest, Sha256};

#[path = "../../../tests/support/frontend.rs"]
mod support;

const END_MESSAGE: u32 = 200010;

fn golden() -> Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../tests/frontend/inkling2_tml.json");
    serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap()
}

struct Inkling {
    frontend: Frontend,
    compiler: crate::grammar::GrammarCompiler,
    config: ModelConfig,
}

impl Inkling {
    fn load(golden: &Value) -> Self {
        let snapshot = std::path::PathBuf::from(std::env::var_os("FLARE_INKLING2_TEST_SNAPSHOT").unwrap());
        let path = snapshot.join("tokenizer.json");
        let sha256 = format!("{:x}", Sha256::digest(std::fs::read(&path).unwrap()));
        assert_eq!(sha256, golden["tokenizer_sha256"], "checkpoint tokenizer differs from the fixture");
        let settings: FrontendSettings = serde_json::from_value(json!({
            "prompt_encoder": 3, "tokenizer": {}, "eos_token_ids": [200006],
            "image_placeholder_token_id": golden["image_placeholder_token_id"],
        }))
        .unwrap();
        let frontend = Frontend::load_with_settings(
            FrontendAssets { tokenizer: Asset { path, sha256, range: None }, tokens: Default::default(), chat_template: None },
            json!({"add_generation_prompt": true}).as_object().unwrap().clone(),
            &settings,
        )
        .unwrap();
        let mut config = support::model_config(crate::model::testing::metadata());
        config.contract.vocabulary = frontend.tokenizer().get_vocab_size(true);
        config.contract.input_vocabulary = config.contract.vocabulary;
        config.contract.vision.max_images = 0;
        config.contract.frontend = serde_json::from_value(json!({
            "tools":{"kind":8,"wrapping_newlines":0,"tag_separator":""},
            "reasoning":{"kind":6,"open":"<|content_thinking|>","close":"<|end_message|>","wrapping_newlines":0,
                         "terminal_markers":[]},
            "assistant_marker":"<|message_model|>",
            "message_end_markers":["<|end_message|>","<|content_model_end_sampling|>"],
            "rejected_tokens":[], "position_dimensions":0
        }))
        .unwrap();
        config.eos_token_ids = vec![200006];
        let compiler = crate::grammar::GrammarCompiler::new(
            frontend.tokenizer(),
            config.contract.vocabulary,
            &config.eos_token_ids,
            &crate::model::reasoning_delimiter_tokens(&frontend, &config.contract.frontend).unwrap(),
        )
        .unwrap();
        Self { frontend, compiler, config }
    }

    fn request(&self, protocol: Protocol, mut body: Value) -> Result<super::super::inference::Request> {
        body["model"] = json!(self.config.model_id);
        Ok(decode(protocol, body, false)?.request)
    }

    /// The prompt before image expansion, through the production lowering and encoder.
    fn render(&self, protocol: Protocol, body: Value) -> Result<crate::frontend::RenderedPrompt> {
        let request = self.request(protocol, body)?;
        let (normalized, raw, options) = template_inputs(&self.frontend, &request, 0)?;
        assert!(raw.is_none());
        self.frontend.render_chat(&normalized, &options)
    }

    fn prepare(&self, body: Value) -> Result<PreparedInference> {
        let request = self.request(Protocol::Chat, body)?;
        prepare_inference(&self.frontend, None, &self.compiler, &self.config, &request, 0, false)
    }
}

fn protocol(name: &str) -> Protocol {
    match name {
        "chat" => Protocol::Chat,
        "responses" => Protocol::Responses,
        "messages" => Protocol::Messages,
        _ => panic!("unknown protocol {name}"),
    }
}

#[test]
#[ignore = "requires FLARE_INKLING2_TEST_SNAPSHOT with the Inkling 2 tokenizer"]
fn prompts_match_tml_renderers_token_for_token() {
    let golden = golden();
    let inkling = Inkling::load(&golden);
    let placeholder = golden["image_placeholder_token_id"].as_u64().unwrap() as u32;
    for case in golden["prompts"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let expected: Vec<u32> = serde_json::from_value(case["input_ids"].clone()).unwrap();
        let rendered = inkling
            .render(Protocol::Chat, case["request"].clone())
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(rendered.token_ids, expected, "{name}");
        assert_eq!(
            rendered.image_sources.len(),
            expected.iter().filter(|&&id| id == placeholder).count(),
            "{name}"
        );
        assert_eq!(inkling.frontend.decode(&rendered.token_ids, false).unwrap(), rendered.text, "{name}");
        let ends = &rendered.message_boundaries;
        assert!(ends.windows(2).all(|w| w[0] < w[1]), "{name}");
        assert!(ends.iter().all(|&end| 0 < end && end < expected.len()), "{name}");
        if rendered.image_sources.is_empty() {
            let prepared = inkling.prepare(case["request"].clone()).unwrap();
            assert_eq!(prepared.prompt.tokens, expected, "{name}");
        }
    }
    let cases: std::collections::HashMap<_, _> = golden["prompts"]
        .as_array()
        .unwrap()
        .iter()
        .map(|case| (case["name"].as_str().unwrap(), &case["input_ids"]))
        .collect();
    for equivalent in golden["equivalent_requests"].as_array().unwrap() {
        let expected: Vec<u32> = serde_json::from_value(cases[equivalent["name"].as_str().unwrap()].clone()).unwrap();
        let rendered = inkling
            .render(protocol(equivalent["protocol"].as_str().unwrap()), equivalent["body"].clone())
            .unwrap();
        assert_eq!(rendered.token_ids, expected, "{equivalent}");
    }
    for case in golden["errors"].as_array().unwrap() {
        let error = inkling
            .render(Protocol::Chat, case["request"].clone())
            .err()
            .unwrap_or_else(|| panic!("{} rendered", case["name"]));
        assert!(error.to_string().contains(case["message"].as_str().unwrap()), "{}: {error}", case["name"]);
    }
}

#[test]
#[ignore = "requires FLARE_INKLING2_TEST_SNAPSHOT with the Inkling 2 tokenizer"]
fn message_endpoints_are_prefixes_of_longer_conversations() {
    let inkling = Inkling::load(&golden());
    let tools = json!([{"type":"function","function":{"name":"lookup","parameters":{"type":"object"}}}]);
    let messages = json!([
        {"role":"system","content":"Be brief."},
        {"role":"user","content":"Find café 世界"},
        {"role":"assistant","reasoning_content":"Search.","content":"",
         "tool_calls":[{"id":"a","type":"function","function":{"name":"lookup","arguments":"{\"q\":\"x\"}"}}]},
        {"role":"tool","tool_call_id":"a","content":"Found"},
        {"role":"assistant","content":"It is here."},
        {"role":"user","content":"Thanks"},
    ]);
    let full = inkling.render(Protocol::Chat, json!({"messages":messages,"tools":tools})).unwrap();
    // The declaration, the system message, the effort and each later message but the last end a prefix.
    assert_eq!(full.message_boundaries.len(), 7);
    for count in 2..messages.as_array().unwrap().len() {
        let prefix = json!(messages.as_array().unwrap()[..count]);
        let partial = inkling.render(Protocol::Chat, json!({"messages":prefix,"tools":tools})).unwrap();
        assert_eq!(&full.token_ids[..partial.token_ids.len()], partial.token_ids.as_slice());
        assert!(full.message_boundaries.contains(&partial.token_ids.len()), "{count}");
    }
    let content = |hint: bool| {
        let mut stable = json!({"type":"text","text":"Stable history."});
        if hint {
            stable["cache_control"] = json!({"type":"ephemeral"});
        }
        json!({"max_tokens":8,"messages":[{"role":"user","content":[stable,{"type":"text","text":"Changing suffix."}]}]})
    };
    let hinted = inkling.render(Protocol::Messages, content(true)).unwrap();
    let plain = inkling.render(Protocol::Messages, content(false)).unwrap();
    assert_eq!(hinted.token_ids, plain.token_ids);
    let effort = plain.message_boundaries[0];
    let stable = effort + plain.token_ids[effort..].iter().position(|&id| id == END_MESSAGE).unwrap() + 1;
    assert!(hinted.message_boundaries.contains(&stable));
    assert!(!plain.message_boundaries.contains(&stable));
}
